paras = [
    "Plants use sunlight for photosynthesis. Photosynthesis produces glucose.",
    "Glucose is broken down in respiration. Respiration releases energy.",
    "Energy drives growth. Growth produces new leaves.",
    "Leaves lose water by transpiration. Transpiration pulls water up the stem.",
]
terms = ["photosynthesis", "glucose", "respiration", "energy", "transpiration"]
from itertools import combinations
counts = {}
for p in paras:
    low = p.lower()
    present = [t for t in terms if t in low]
    for a, b in combinations(sorted(present), 2):
        counts[(a, b)] = counts.get((a, b), 0) + 1
for pair, n in sorted(counts.items()):
    print(pair[0], "+", pair[1], ":", n)

def shorten(text, limit):
