def summarize(data):
    lines = []
    for region, vals in data.items():
        lines.append(f"{region} total {sum(vals)} best {max(vals)}")
    return lines

data = {"north": [12, 15, 9], "south": [20, 8, 11], "east": [5, 5, 6]}
for line in summarize(data):
    print(line)

def summarize_numbers(nums):
    if not nums:
        return None
    s = sorted(nums)
    n = len(s)
    median = s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2
    return {"count": n, "min": s[0], "max": s[-1], "median": median}

tests = [
    ([3, 1, 2], {"count": 3, "min": 1, "max": 3, "median": 2}),
    ([4, 1, 3, 2], {"count": 4, "min": 1, "max": 4, "median": 2.5}),
    ([], None),
    ([7], {"count": 1, "min": 7, "max": 7, "median": 7}),
]
for nums, expected in tests:
    got = summarize_numbers(nums)
    print(nums, "->", got, "PASS" if got == expected else "FAIL")

